// Turn the agent's search options into a Supabase (PostgREST) filter string.
// Every input is optional; anything missing or unrecognised is simply not filtered on.
const i = $input.first().json;
const clean = s => String(s ?? '').trim();
const parts = [];
const rawCompany = clean(i.company);
const company = /^(any|all|none|null|n\/a|-)?$/i.test(rawCompany) ? '' : rawCompany.replace(/[^A-Za-z0-9-]+/g, '*').replace(/^\*+|\*+$/g, '');
if (company) parts.push(`company=ilike.*${company}*`);
const severity = clean(i.severity).toLowerCase();
if (['strong', 'decent', 'skip'].includes(severity)) parts.push(`severity=eq.${severity}`);
const stage = clean(i.stage).toLowerCase();
if (/^[a-z_]+$/.test(stage) && stage !== 'any') parts.push(`stage=eq.${stage}`);
const days = Number(i.days) || 0;
if (days > 0) parts.push(`first_seen=gte.${new Date(Date.now() - days * 864e5).toISOString()}`);
const limit = Math.min(Math.max(Number(i.limit) || 20, 1), 50);
// An empty filter would match everything; "id=not.is.null" is a harmless always-true filter.
return [{ json: { filter: parts.length ? parts.join('&') : 'id=not.is.null', limit } }];

// Keep one row per duplicate group, sort by score and return a compact list to the agent.
const limit = $('Build filter').first().json.limit;
const rows = $input.all().map(x => x.json)
  .filter(r => r.id && (r.dedup_group == null || r.dedup_group === r.id));
rows.sort((a, b) => (b.fit_score ?? -1) - (a.fit_score ?? -1));
const roles = rows.slice(0, limit).map(r => ({
  company: r.company, title: r.title, location: r.location,
  score: r.fit_score, severity: r.severity, stage: r.stage,
  eligibility: r.eligibility, why: r.why,
  first_seen: String(r.first_seen || '').slice(0, 10), url: r.url,
}));
return [{ json: { total_matches: rows.length, returned: roles.length, roles } }];
